const root = process.env.ZODY_CUA_PLUGIN_ROOT ?? process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import('node:path'); const { pathToFileURL } = await import('node:url');
const { setupComputerUseRuntime } = await import(pathToFileURL(join(root, 'scripts', 'computer-use-client.mjs')).href); await setupComputerUseRuntime({ globals: globalThis });
const { readFile, writeFile, rename } = await import('node:fs/promises');
const directory = '{{e2eRuntimeRoot}}/cua-r1-c';
const f = JSON.parse(await readFile(join(directory, 'manifest.json'), 'utf8'));
const pause = ms => new Promise(r => setTimeout(r, ms));
const control = async name => { try { return JSON.parse(await readFile(join(directory,name),'utf8')); } catch (e) { if(e.code==='ENOENT') return null; throw e; } };
for(let index=0;index<20;index++) {
 if((await control('complete.json'))?.complete===true) break;
 const intent=join(directory,`intent-${index}.json`);await writeFile(intent+'.tmp',JSON.stringify({index}));await rename(intent+'.tmp',intent);
 const value=await agent.computerUse.computer.get_app_state({app_ref:{pid:f.pid,window_id:f.targetWindow},disable_diffing:true,tree_shown_to_model:false});
 const text=typeof value==='string'?value:JSON.stringify(value);
 const result={index,received:true,targetSeen:text.includes(f.targetMarker),siblingSeen:text.includes(f.siblingMarker),isError:!text.includes('AX window state')};
 const destination=join(directory,`result-${index}.json`);await writeFile(destination+'.tmp',JSON.stringify(result));await rename(destination+'.tmp',destination); nodeRepl.write('R1_C:'+JSON.stringify(result));
 for(let n=0;;n++){if(await control(`ack-${index}.json`))break;if(n>1600)throw Error('R1_C_CONTROLLER_TIMEOUT');await pause(25);}
}
nodeRepl.write('R1_C_PAGE_1_DONE');

